    baseline_total = np.sum(baseline_logprobs, axis=1)
    no_result_total = np.sum(no_result_logprobs, axis=1)

    margins = np.maximum(candidate_total - baseline_total, candidate_total - no_result_total)
    keep_mask = margins > tau_filter
    return keep_mask, margins
